import{_ as l,a0 as d,w as o,s as c,ao as t,I as p,x as a,a1 as i,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"Linux 上靜態鏈接庫工作原理 | LCTT x X-CMD","titleTemplate":false,"description":"Linux 上靜態鏈接庫工作原理 | LCTT (202207) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux 上靜態鏈接庫工作原理 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux 上靜態鏈接庫工作原理 | LCTT (202207) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202207/20220603 How static linking works on Linux","title":"Linux 上靜態鏈接庫工作原理","tag":"202207","desc":""},"relativePath":"202207/20220603 How static linking works on Linux.md","filePath":"[post].md"}'),r={name:"202207/20220603 How static linking works on Linux.md"};function h(u,s,b,g,k,m){const n=d("Link");return o(),c("div",null,[s[21]||(s[21]=t('<h1 id="linux-上靜態鏈接庫工作原理" tabindex="-1">Linux 上靜態鏈接庫工作原理 <a class="header-anchor" href="#linux-上靜態鏈接庫工作原理" aria-label="Permalink to “Linux 上靜態鏈接庫工作原理”">​</a></h1><p><img src="https://img.linux.net.cn/data/attachment/album/202207/12/120441y0q5a5abfyjyy7ug.jpg" alt=""></p><blockquote><p>學習如何用靜態鏈接庫將多個 C 目標文件結合到一個單個的可執行文件之中。</p></blockquote><p>使用 C 編寫的應用程序時，通常有多個源碼文件，但最終你需要編譯成單個的可執行文件。</p><p>你可以通過兩種方式來完成這項工作：通過創建一個 <ruby>靜態<rt>static</rt></ruby> 庫 或 一個 <ruby>動態<rt>dynamic</rt></ruby> 庫（也被稱為 <ruby>共享<rt>shared</rt></ruby> 庫）。從創建和鏈接的方式來看，它們是兩種不同類型的庫。選擇使用哪種方式取決於你的的具體場景。</p>',5)),p("p",null,[s[1]||(s[1]=a("在 ",-1)),i(n,{href:"https://linux.cn/article-14813-1.html"},{default:e(()=>[...s[0]||(s[0]=[a("上一篇文章",-1)])]),_:1}),s[2]||(s[2]=a(" 中，我演示瞭如何創建一個動態鏈接的可執行文件，這是一種更通用的方法。在這篇文章中，我將説明如何創建一個靜態鏈接的可執行文件。",-1))]),s[22]||(s[22]=t(`<h3 id="使用靜態庫鏈接器" tabindex="-1">使用靜態庫鏈接器 <a class="header-anchor" href="#使用靜態庫鏈接器" aria-label="Permalink to “使用靜態庫鏈接器”">​</a></h3><p><ruby>鏈接器<rt>linker</rt></ruby>是一個命令，它將一個程序的多個部分結合在一起，併為它們重新組織內存分配。</p><p>鏈接器的功能包括：</p><ul><li>整合一個程序的所有的部分</li><li>計算出一個新的內存組織結構，以便所有的部分組合在一起</li><li>恢復內存地址，以便程序可以在新的內存組織結構下運行</li><li>解析符號引用</li></ul><p>鏈接器通過這些功能，創建了一個名稱為可執行文件的一個可運行程序。</p><p>靜態庫是通過複製一個程序中的所有依賴庫模組到最終的可執行鏡像來創建的。鏈接器將鏈接靜態庫作為編譯過程的最後一步。可執行文件是通過解析外部引用、將庫例程與程序代碼結合在一起來創建的。</p><h3 id="創建目標文件" tabindex="-1">創建目標文件 <a class="header-anchor" href="#創建目標文件" aria-label="Permalink to “創建目標文件”">​</a></h3><p>這裏是一個靜態庫的示例以及其鏈接過程。首先，創建帶有這些函數識別標誌的頭文件 <code>mymath.h</code> :</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>int add(int a, int b);</span></span>
<span class="line"><span>int sub(int a, int b);</span></span>
<span class="line"><span>int mult(int a, int b);</span></span>
<span class="line"><span>int divi(int a, int b);</span></span></code></pre></div><p>使用這些函數定義來創建 <code>add.c</code> 、<code>sub.c</code> 、<code>mult.c</code> 和 <code>divi.c</code> 文件。我將把所有的代碼都放置到一個代碼塊中，請將其分為四個文件，如註釋所示：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>// add.c</span></span>
<span class="line"><span>int add(int a, int b){</span></span>
<span class="line"><span>return (a+b);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//sub.c</span></span>
<span class="line"><span>int sub(int a, int b){</span></span>
<span class="line"><span>return (a-b);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//mult.c</span></span>
<span class="line"><span>int mult(int a, int b){</span></span>
<span class="line"><span>return (a*b);</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>//divi.c</span></span>
<span class="line"><span>int divi(int a, int b){</span></span>
<span class="line"><span>return (a/b);</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>現在，使用 GCC 來生成目標文件 <code>add.o</code> 、<code>sub.o</code> 、<code>mult.o</code> 和 <code>divi.o</code>：</p><p>（LCTT 校注：關於“<ruby>目標文件<rt>object file</rt></ruby>”，有時候也被稱作“對象文件”，對此，存在一些譯法混亂情形，稱之為“目標文件”的譯法比較流行，本文采用此譯法。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -c add.c sub.c mult.c divi.c</span></span></code></pre></div><p><code>-c</code> 選項跳過鏈接步驟，而只創建目標文件。</p><p>創建一個名稱為 <code>libmymath.a</code> 的靜態庫，接下來，移除目標文件，因為它們不再被需要。（注意，使用一個 <code>trash</code> 命令比使用一個 <code>rm</code> 命令更安全。）</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ar rs libmymath.a add.o sub.o mult.o divi.o</span></span>
<span class="line"><span>$ trash *.o</span></span>
<span class="line"><span>$ ls</span></span>
<span class="line"><span>add.c  divi.c  libmymath.a  mult.c  mymath.h  sub.c</span></span></code></pre></div><p>現在，你已經創建了一個名稱為 <code>libmymath</code> 的簡單數學示例庫，你可以在 C 代碼中使用它。當然，也有非常複雜的 C 庫，這就是他們這些開發者來生成最終產品的工藝流程，你和我可以安裝這些庫並在 C 代碼中使用。</p><p>接下來，在一些自定義代碼中使用你的數學庫，然後鏈接它。</p><h3 id="創建一個靜態鏈接的應用程序" tabindex="-1">創建一個靜態鏈接的應用程序 <a class="header-anchor" href="#創建一個靜態鏈接的應用程序" aria-label="Permalink to “創建一個靜態鏈接的應用程序”">​</a></h3><p>假設你已經為數學運算編寫了一個命令。創建一個名稱為 <code>mathDemo.c</code> 的文件，並將這些代碼複製粘貼至其中：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>#include &lt;mymath.h&gt;</span></span>
<span class="line"><span>#include &lt;stdio.h&gt;</span></span>
<span class="line"><span>#include &lt;stdlib.h&gt;</span></span>
<span class="line"><span></span></span>
<span class="line"><span>int main()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>  int x, y;</span></span>
<span class="line"><span>  printf(&quot;Enter two numbers\\n&quot;);</span></span>
<span class="line"><span>  scanf(&quot;%d%d&quot;,&amp;x,&amp;y);</span></span>
<span class="line"><span> </span></span>
<span class="line"><span>  printf(&quot;\\n%d + %d = %d&quot;, x, y, add(x, y));</span></span>
<span class="line"><span>  printf(&quot;\\n%d - %d = %d&quot;, x, y, sub(x, y));</span></span>
<span class="line"><span>  printf(&quot;\\n%d * %d = %d&quot;, x, y, mult(x, y));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>  if(y==0){</span></span>
<span class="line"><span>    printf(&quot;\\nDenominator is zero so can&#39;t perform division\\n&quot;);</span></span>
<span class="line"><span>      exit(0);</span></span>
<span class="line"><span>  }else{</span></span>
<span class="line"><span>      printf(&quot;\\n%d / %d = %d\\n&quot;, x, y, divi(x, y));</span></span>
<span class="line"><span>      return 0;</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span></code></pre></div><p>注意：第一行是一個 <code>include</code> 語句，通過名稱來引用你自己的 <code>libmymath</code> 庫。</p><p>針對 <code>mathDemo.c</code> 創建一個名稱為 <code>mathDemo.o</code> 的對象文件:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -I . -c mathDemo.c</span></span></code></pre></div><p><code>-I</code> 選項告訴 GCC 搜索在其後列出的頭文件。在這個實例中，你通過單個點（<code>.</code>）來指定當前目錄。</p><p>鏈接 <code>mathDemo.o</code> 和 <code>libmymath.a</code> 來生成最終的可執行文件。這裏有兩種方法來向 GCC 告知這一點。</p><p>你可以指向文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -static -o mathDemo mathDemo.o libmymath.a</span></span></code></pre></div><p>或者，你可以具體指定庫的路徑及名稱：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ gcc -static -o mathDemo -L . mathDemo.o -lmymath</span></span></code></pre></div><p>在後面的那個示例中，<code>-lmymath</code> 選項告訴鏈接器來鏈接對象文件 <code>mathDemo.o</code> 和對象文件 <code>libmymath.a</code> 來生成最終的可執行文件。<code>-L</code> 選項指示鏈接器在下面的參數中查找庫（類似於你使用 <code>-I</code> 所做的工作）。</p><h3 id="分析結果" tabindex="-1">分析結果 <a class="header-anchor" href="#分析結果" aria-label="Permalink to “分析結果”">​</a></h3><p>使用 <code>file</code> 命令來驗證它是靜態鏈接的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ file mathDemo</span></span>
<span class="line"><span>mathDemo: ELF 64-bit LSB executable, x86-64...</span></span>
<span class="line"><span>statically linked, with debug_info, not stripped</span></span></code></pre></div><p>使用 <code>ldd</code> 命令，你將會看到該可執行文件不是動態鏈接的：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ldd ./mathDemo</span></span>
<span class="line"><span>        not a dynamic executable</span></span></code></pre></div><p>你也可以查看 <code>mathDemo</code> 可執行文件的大小：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ du -h ./mathDemo</span></span>
<span class="line"><span>932K    ./mathDemo</span></span></code></pre></div>`,39)),p("p",null,[s[4]||(s[4]=a("在我 ",-1)),i(n,{href:"https://linux.cn/article-14813-1.html"},{default:e(()=>[...s[3]||(s[3]=[a("前一篇文章",-1)])]),_:1}),s[5]||(s[5]=a(" 的示例中，動態鏈接的可執行文件只佔有 24K 大小。",-1))]),s[23]||(s[23]=t(`<p>運行該命令來看看它的工作內容：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>$ ./mathDemo</span></span>
<span class="line"><span>Enter two numbers</span></span>
<span class="line"><span>10</span></span>
<span class="line"><span>5</span></span>
<span class="line"><span></span></span>
<span class="line"><span>10 + 5 = 15</span></span>
<span class="line"><span>10 - 5 = 5</span></span>
<span class="line"><span>10 * 5 = 50</span></span>
<span class="line"><span>10 / 5 = 2</span></span></code></pre></div><p>看起來令人滿意！</p><h3 id="何時使用靜態鏈接" tabindex="-1">何時使用靜態鏈接 <a class="header-anchor" href="#何時使用靜態鏈接" aria-label="Permalink to “何時使用靜態鏈接”">​</a></h3><p>動態鏈接可執行文件通常優於靜態鏈接可執行文件，因為動態鏈接會保持應用程序的組件模組化。假如一個庫接收到一次關鍵安全更新，那麼它可以很容易地修補，因為它存在於應用程序的外部。</p><p>當你使用靜態鏈接時，庫的代碼會“隱藏”在你創建的可執行文件之中，意味着在庫每次更新時（相信我，你會有更好的東西），僅有的一種修補方法是重新編譯和發佈一個新的可執行文件。</p><p>不過，如果一個庫的代碼，要麼存在於它正在使用的具有相同代碼的可執行文件中，要麼存在於不會接收到任何更新的專用嵌入式設備中，那麼靜態連接將是一種可接受的選項。</p><hr>`,8)),p("p",null,[s[7]||(s[7]=a("via: ",-1)),i(n,{href:"https://opensource.com/article/22/6/static-linking-linux"},{default:e(()=>[...s[6]||(s[6]=[a("https://opensource.com/article/22/6/static-linking-linux",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=a("作者：",-1)),i(n,{href:"https://opensource.com/users/jayashree-huttanagoudar"},{default:e(()=>[...s[8]||(s[8]=[a("Jayashree Huttanagoudar",-1)])]),_:1}),s[13]||(s[13]=a(" 選題：",-1)),i(n,{href:"https://github.com/lkxed"},{default:e(()=>[...s[9]||(s[9]=[a("lkxed",-1)])]),_:1}),s[14]||(s[14]=a(" 譯者：",-1)),i(n,{href:"https://github.com/robsean"},{default:e(()=>[...s[10]||(s[10]=[a("robsean",-1)])]),_:1}),s[15]||(s[15]=a(" 校對：",-1)),i(n,{href:"https://github.com/turbokernel"},{default:e(()=>[...s[11]||(s[11]=[a("turbokernel",-1)])]),_:1})]),p("p",null,[s[18]||(s[18]=a("本文由 ",-1)),i(n,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...s[16]||(s[16]=[a("LCTT",-1)])]),_:1}),s[19]||(s[19]=a(" 原創編譯，",-1)),i(n,{href:"https://linux.cn/"},{default:e(()=>[...s[17]||(s[17]=[a("Linux中國",-1)])]),_:1}),s[20]||(s[20]=a(" 榮譽推出",-1))])])}const C=l(r,[["render",h]]);export{x as __pageData,C as default};
